    lowered = cleaned.lower()
    bracket = re.search(r"\[(nyse|nasdaq|nyse american|nyse arca)\s*:", lowered)
    if bracket:
        token = bracket.group(1).upper()
        if token == "NYSE":
            return "NYSE"
        if token == "NASDAQ":
            return "NASDAQ"
        if token == "NYSE AMERICAN":
            return "NYSE American"
        if token == "NYSE ARCA":
